function BulletinBoard:GetUIParamByName(szName)
	if BulletinBoard.Config[szName] ~= nil then
		return BulletinBoard.Config[szName].DlgFile,BulletinBoard.Config[szName].DlgName,BulletinBoard.Config[szName].ID
	end

	return --[[!AUTO_259]][====[]====],--[[!AUTO_260]][====[]====],0
end

function BulletinBoard:GetLogicParamByName(szName)
	if BulletinBoard.Config[szName] ~= nil then
		return BulletinBoard.Config[szName].scene_id,BulletinBoard.Config[szName].xpos,BulletinBoard.Config[szName].ypos
	end

	return 0,0,0
end
